er_seconds": 20}, {"key": "p2.f2", "part": 2, "kind": "question", "body": "Do you often talk to this person?", "answer_seconds": 20}, {"key": "p3.intro", "part": 3, "kind": "say", "body": "Thank you. Part three. We've been talking about a person in your family you admire. Now I'd like to ask you some more general questions about families."}, {"key": "p3.q1", "part": 3, "kind": "question", "body": "Do people in your country often live with their grandparents?", "answer_seconds": 45}, {"key": "p3.q2", "part": 3, "kind": "question", "body": "What can young people learn from older people?", "answer_seconds": 45}, {"key": "p3.q3", "part": 3, "kind": "question", "body": "How are families today different from families in the past?", "answer_seconds": 45}, {"key": "p3.q4", "part": 3, "kind": "question", "body": "Who should look after older people, their family or the government? Why?", "answer_seconds": 45}, {"key": "end", "part": 4, "kind": "say", "body": "Thank you. That is the end of the speaking test."}]$l$::jsonb; errors text[];
